import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.D7WGirly.js";const m=JSON.parse('{"title":"Financial Forecast — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"financial-forecast-04-troubleshooting-and-faqs.md","filePath":"financial-forecast-04-troubleshooting-and-faqs.md"}'),i={name:"financial-forecast-04-troubleshooting-and-faqs.md"};function s(r,e,l,h,c,d){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="financial-forecast-—-troubleshooting-faqs" tabindex="-1">Financial Forecast — Troubleshooting &amp; FAQs <a class="header-anchor" href="#financial-forecast-—-troubleshooting-faqs" aria-label="Permalink to &quot;Financial Forecast — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common issues, edge cases, and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="who-can-create-and-edit-financial-models" tabindex="-1">Who can create and edit financial models? <a class="header-anchor" href="#who-can-create-and-edit-financial-models" aria-label="Permalink to &quot;Who can create and edit financial models?&quot;">​</a></h3><p>Any workspace member can create and edit financial models. There are no admin-only restrictions.</p><h3 id="can-a-feature-have-more-than-one-financial-model" tabindex="-1">Can a Feature have more than one financial model? <a class="header-anchor" href="#can-a-feature-have-more-than-one-financial-model" aria-label="Permalink to &quot;Can a Feature have more than one financial model?&quot;">​</a></h3><p>Yes. A Feature can have multiple models — useful for comparing a conservative and optimistic scenario, or modeling different approaches to building the Feature. Use the model selector dropdown on the Financial Forecast tab to switch between models.</p><h3 id="can-i-rename-a-model" tabindex="-1">Can I rename a model? <a class="header-anchor" href="#can-i-rename-a-model" aria-label="Permalink to &quot;Can I rename a model?&quot;">​</a></h3><p>Yes. Model names are editable from the Settings panel within the model view. The default name is <code>[Feature Name] Financial Forecast</code>.</p><h3 id="can-i-delete-a-model" tabindex="-1">Can I delete a model? <a class="header-anchor" href="#can-i-delete-a-model" aria-label="Permalink to &quot;Can I delete a model?&quot;">​</a></h3><p>Yes. Open the model Settings panel and select Delete Model. Deletion is permanent — all assumptions and calculated metrics for that model are removed. This cannot be undone.</p><h3 id="what-is-the-discount-rate-and-what-should-i-set-it-to" tabindex="-1">What is the discount rate and what should I set it to? <a class="header-anchor" href="#what-is-the-discount-rate-and-what-should-i-set-it-to" aria-label="Permalink to &quot;What is the discount rate and what should I set it to?&quot;">​</a></h3><p>The discount rate is used to calculate NPV. It represents your organization&#39;s cost of capital or the minimum acceptable return on investment. The default is 12%. Common choices:</p><ul><li><strong>8–10%</strong> — lower-risk organizations, stable markets</li><li><strong>12–15%</strong> — typical for growth-stage SaaS companies</li><li><strong>20%+</strong> — high-uncertainty environments, early-stage companies</li></ul><p>If you&#39;re unsure, check with your finance team. Using a consistent rate across all models is more important than the specific value you choose.</p><h3 id="does-changing-the-org-level-default-discount-rate-update-existing-models" tabindex="-1">Does changing the org-level default discount rate update existing models? <a class="header-anchor" href="#does-changing-the-org-level-default-discount-rate-update-existing-models" aria-label="Permalink to &quot;Does changing the org-level default discount rate update existing models?&quot;">​</a></h3><p>No. Changes to org-level defaults apply only to new models created after the change. Existing models retain their individually set discount rates.</p><h3 id="can-i-link-quotes-from-other-features-to-my-model" tabindex="-1">Can I link quotes from other Features to my model? <a class="header-anchor" href="#can-i-link-quotes-from-other-features-to-my-model" aria-label="Permalink to &quot;Can I link quotes from other Features to my model?&quot;">​</a></h3><p>No. Evidence linking is limited to quotes already associated with the Feature the model belongs to. To link a quote from another Feature, you would need to first associate that quote with the current Feature.</p><h3 id="what-does-the-completeness-score-in-the-compare-view-mean" tabindex="-1">What does the completeness score in the Compare view mean? <a class="header-anchor" href="#what-does-the-completeness-score-in-the-compare-view-mean" aria-label="Permalink to &quot;What does the completeness score in the Compare view mean?&quot;">​</a></h3><p>Completeness reflects how fully the model&#39;s assumptions have been filled in. A model with many empty or zero-value fields will have a low completeness score. Incompletely filled models may have unreliable metrics — review them before using their output for decisions.</p><h3 id="can-the-excel-export-be-imported-back-into-lodestone" tabindex="-1">Can the Excel export be imported back into Lodestone? <a class="header-anchor" href="#can-the-excel-export-be-imported-back-into-lodestone" aria-label="Permalink to &quot;Can the Excel export be imported back into Lodestone?&quot;">​</a></h3><p>No. The Excel export is a read-only output for sharing and archiving purposes. It cannot be used to import data back into Lodestone.</p><h3 id="does-financial-forecast-affect-rice-scores-or-other-feature-evaluation-fields" tabindex="-1">Does Financial Forecast affect RICE scores or other Feature evaluation fields? <a class="header-anchor" href="#does-financial-forecast-affect-rice-scores-or-other-feature-evaluation-fields" aria-label="Permalink to &quot;Does Financial Forecast affect RICE scores or other Feature evaluation fields?&quot;">​</a></h3><p>No. Financial Forecast is a separate module and its calculated metrics (NPV, ROI, IRR, payback) do not feed into RICE scores or any other evaluation field. They are displayed in the Financial Forecast tab and the Compare view only.</p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="metrics-show-as-0-or-blank-after-adding-assumptions" tabindex="-1">Metrics show as 0 or blank after adding assumptions <a class="header-anchor" href="#metrics-show-as-0-or-blank-after-adding-assumptions" aria-label="Permalink to &quot;Metrics show as 0 or blank after adding assumptions&quot;">​</a></h3><p>Check the following:</p><ul><li>Make sure the assumption&#39;s <strong>Baseline</strong> and <strong>Delta</strong> fields have non-zero values</li><li>Verify the <strong>Category</strong> is set correctly (Revenue Up, Revenue Down, Cost Up, Cost Down)</li><li>Confirm the <strong>Start Month</strong> is set to 1 or later (not 0)</li></ul><p>Metrics recalculate automatically when any assumption is saved — if something still looks wrong after checking these fields, try refreshing the page.</p><h3 id="npv-is-negative-even-though-revenue-assumptions-are-positive" tabindex="-1">NPV is negative even though revenue assumptions are positive <a class="header-anchor" href="#npv-is-negative-even-though-revenue-assumptions-are-positive" aria-label="Permalink to &quot;NPV is negative even though revenue assumptions are positive&quot;">​</a></h3><p>A negative NPV can occur when:</p><ul><li>Cost assumptions outweigh revenue assumptions over the modeled period</li><li>The discount rate is high relative to the returns being modeled</li><li>The payback period extends beyond the modeled horizon (meaning costs are paid upfront but revenue ramps slowly)</li></ul><p>Review the assumption breakdown to identify which assumptions are contributing most to costs. If NPV is negative only in the base case but positive in the Bull case, that&#39;s a legitimate range to document and present.</p><h3 id="bull-bear-metrics-aren-t-showing" tabindex="-1">Bull/Bear metrics aren&#39;t showing <a class="header-anchor" href="#bull-bear-metrics-aren-t-showing" aria-label="Permalink to &quot;Bull/Bear metrics aren&#39;t showing&quot;">​</a></h3><p>Bull and Bear metrics only appear when at least one assumption has both a Bull value and a Bear value entered. If the scenario columns are missing or blank, check that you&#39;ve filled in both fields (not just one) for your key assumptions.</p><h3 id="the-compare-view-isn-t-showing-my-feature" tabindex="-1">The Compare view isn&#39;t showing my Feature <a class="header-anchor" href="#the-compare-view-isn-t-showing-my-feature" aria-label="Permalink to &quot;The Compare view isn&#39;t showing my Feature&quot;">​</a></h3><p>The Compare view only shows Features that have at least one financial model. Features without any model will appear with blank metric fields. If a Feature is missing entirely, open it from the backlog and create a model on the Financial Forecast tab.</p><h3 id="the-export-button-isn-t-downloading-anything" tabindex="-1">The Export button isn&#39;t downloading anything <a class="header-anchor" href="#the-export-button-isn-t-downloading-anything" aria-label="Permalink to &quot;The Export button isn&#39;t downloading anything&quot;">​</a></h3><p>Try refreshing the page and attempting the export again. If the problem persists, check that your browser isn&#39;t blocking downloads from this site.</p><h3 id="i-can-t-find-the-financial-forecast-tab-on-a-feature" tabindex="-1">I can&#39;t find the Financial Forecast tab on a Feature <a class="header-anchor" href="#i-can-t-find-the-financial-forecast-tab-on-a-feature" aria-label="Permalink to &quot;I can&#39;t find the Financial Forecast tab on a Feature&quot;">​</a></h3><p>The Financial Forecast tab is the second tab on the Feature Detail page. If you don&#39;t see it, confirm you&#39;re on the Feature Detail page (accessed by clicking the Feature name) rather than a Roadmap or Release view.</p><hr><p><em>This is version 1 of the Financial Forecast documentation, documenting confirmed platform behavior.</em></p>',46)])])}const p=a(i,[["render",s]]);export{m as __pageData,p as default};
